package io.github.ccch1mneyyy.dsh_app.phone.shell;

import android.os.Bundle;
import android.system.Os;
import android.system.OsConstants;
import java.io.ByteArrayOutputStream;
import java.io.FileInputStream;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

/** Module-owned replacement entry point; wire shape mirrors the target shell service. */
public final class AndroidShellMain {
    private static final String REVISION="dsh.android-shell.v1";private static final Map<String,Job> JOBS=new ConcurrentHashMap<>();private static final Set<String> RETIRED=new HashSet<>();private static final Set<String> CANCELLED_BEFORE_START=new HashSet<>();private static final String INSTANCE=java.util.UUID.randomUUID().toString();private static volatile Integer binderCallerUid;
    private AndroidShellMain(){}
    public static void main(String[] args)throws Exception{OutputStream out=System.out;try{out.write(RelaxedShellWire.MAGIC);out.flush();while(true){Bundle request=RelaxedShellWire.readBundle(System.in);if(request==null)break;RelaxedShellWire.writeBundle(out,handle(request));if("destroy".equals(request.getString("op")))break;}}finally{destroyExternal();}}
    static Bundle handleExternal(Bundle request){int caller=android.os.Binder.getCallingUid();synchronized(JOBS){if(binderCallerUid==null)binderCallerUid=caller;else if(binderCallerUid!=caller)return RelaxedShellWire.result(false,"identityChanged");}return handle(request);}
    static void destroyExternal(){for(Job job:JOBS.values())job.cancel(false);JOBS.clear();synchronized(JOBS){binderCallerUid=null;RETIRED.clear();CANCELLED_BEFORE_START.clear();}}
    private static Bundle handle(Bundle request){if(!REVISION.equals(request.getString("revision")))return RelaxedShellWire.result(false,"protocolMismatch");String op=request.getString("op");if("probe".equals(op)){Bundle b=RelaxedShellWire.result(true,null);b.putString("revision",REVISION);b.putString("instance",INSTANCE);b.putInt("uid",android.os.Process.myUid());return b;}if(!INSTANCE.equals(request.getString("instance")))return RelaxedShellWire.result(false,"identityChanged");String id=request.getString("jobId");if("start".equals(op)){String command=request.getString("command");long timeout=request.getLong("timeoutMs",0L);if(request.getInt("uid",-1)!=android.os.Process.myUid())return RelaxedShellWire.result(false,"identityChanged");if(id==null||!id.matches("[a-zA-Z0-9-]{1,64}")||command==null||command.indexOf('\0')>=0||timeout<100L)return RelaxedShellWire.result(false,"invalidArguments");synchronized(JOBS){if(JOBS.containsKey(id)||RETIRED.contains(id))return RelaxedShellWire.result(false,"cancelled");if(CANCELLED_BEFORE_START.remove(id)){remember(id);return RelaxedShellWire.result(false,"cancelled");}for(Job job:JOBS.values())if(!job.done)return RelaxedShellWire.result(false,"busy");Job job=new Job(id,command,timeout);JOBS.put(id,job);job.start();return job.snapshot();}}if("poll".equals(op)){Job job=JOBS.get(id);if(job!=null)return job.snapshot();synchronized(JOBS){return RelaxedShellWire.result(false,RETIRED.contains(id)?"cancelled":"jobNotFound");}}if("cancel".equals(op)){if(id==null||!id.matches("[a-zA-Z0-9-]{1,64}"))return RelaxedShellWire.result(false,"invalidArguments");synchronized(JOBS){remember(id);Job job=JOBS.get(id);if(job==null)CANCELLED_BEFORE_START.add(id);else job.cancel(false);}return RelaxedShellWire.result(true,null);}if("destroy".equals(op)){destroyExternal();return RelaxedShellWire.result(true,null);}return RelaxedShellWire.result(false,"invalidArguments");}
    private static void remember(String id){RETIRED.add(id);while(RETIRED.size()>64)RETIRED.remove(RETIRED.iterator().next());while(CANCELLED_BEFORE_START.size()>64)CANCELLED_BEFORE_START.remove(CANCELLED_BEFORE_START.iterator().next());}
    private static final class Job{final String id,command;final long timeout;final ByteArrayOutputStream stdout=new ByteArrayOutputStream(),stderr=new ByteArrayOutputStream();final Object lock=new Object();volatile Process process;volatile int childPid=-1;volatile boolean started,done,timedOut,cancelled,truncated;volatile int exitCode=-1;volatile String error;Job(String id,String command,long timeout){this.id=id;this.command=command;this.timeout=timeout;}void start(){Thread worker=new Thread(this::run,"dsh-shell-job");worker.setDaemon(true);worker.start();Thread deadline=new Thread(()->{try{Thread.sleep(timeout);if(!done)cancel(true);}catch(InterruptedException ignored){}} ,"dsh-shell-deadline");deadline.setDaemon(true);deadline.start();}void run(){try{ProcessBuilder pb=new ProcessBuilder("/system/bin/app_process","/system/bin",AndroidShellJobMain.class.getName(),Long.toString(timeout),command);shellHelperEnvironment(pb.environment());process=pb.start();byte[] header=new byte[96];int n=0,r;while(n<header.length&&(r=process.getInputStream().read(header,n,1))>0){n+=r;if(header[n-1]=='\n')break;}String line=new String(header,0,n,StandardCharsets.US_ASCII);boolean valid=line.matches("DSH_SHELL_JOB [1-9][0-9]*\\n");if(valid)try{childPid=Integer.parseInt(line.substring(14,line.length()-1));}catch(NumberFormatException e){valid=false;}if(valid)valid=validateChild(childPid);if(!valid){error="identityChanged";cancel(false);}else{started=true;process.getOutputStream().write(1);process.getOutputStream().flush();}Thread err=drain(process.getErrorStream(),stderr),out=drain(process.getInputStream(),stdout);exitCode=process.waitFor();err.join(500);out.join(500);if(err.isAlive()||out.isAlive()){truncated=true;error="outputIncomplete";}}catch(Throwable t){if(error==null)error="executionFailed";}finally{done=true;if(process!=null)process.destroy();}}boolean validateChild(int pid){try{String stat=read("/proc/"+pid+"/stat");int close=stat.lastIndexOf(") ");if(close<0)return false;String[] f=stat.substring(close+2).trim().split(" +");if(f.length<4||!f[1].equals(Integer.toString(android.os.Process.myPid()))||!f[2].equals(Integer.toString(pid))||!f[3].equals(Integer.toString(pid)))return false;for(String line:read("/proc/"+pid+"/status").split("\\n"))if(line.startsWith("Uid:"))return line.substring(4).trim().split(" +")[0].equals(Integer.toString(android.os.Process.myUid()));}catch(Throwable ignored){}return false;}String read(String path)throws java.io.IOException{FileInputStream in=new FileInputStream(path);ByteArrayOutputStream b=new ByteArrayOutputStream();try{byte[] x=new byte[4096];int n;while((n=in.read(x))>=0)b.write(x,0,n);return new String(b.toByteArray(),StandardCharsets.US_ASCII);}finally{in.close();}}Thread drain(InputStream in,ByteArrayOutputStream target){Thread t=new Thread(()->{byte[] b=new byte[4096];try{int n;while((n=in.read(b))>=0)synchronized(lock){int keep=Math.min(n,64*1024-stdout.size()-stderr.size());if(keep>0)target.write(b,0,keep);if(keep<n)truncated=true;}}catch(Throwable ignored){}} ,"dsh-shell-drain");t.setDaemon(true);t.start();return t;}void cancel(boolean timeout){if(timeout){timedOut=true;error="timeout";}else if(!done){cancelled=true;if(error==null)error="cancelled";}Process p=process;if(p!=null){try{if(childPid>1)Os.kill(-childPid,OsConstants.SIGKILL);}catch(Throwable ignored){}p.destroy();}}Bundle snapshot(){synchronized(lock){Bundle b=RelaxedShellWire.result(error==null,error);b.putString("jobId",id);b.putBoolean("started",started);b.putBoolean("done",done);b.putString("stdout",new String(stdout.toByteArray(),StandardCharsets.UTF_8));b.putString("stderr",new String(stderr.toByteArray(),StandardCharsets.UTF_8));if(done)b.putInt("exitCode",exitCode);b.putBoolean("timedOut",timedOut);b.putBoolean("cancelled",cancelled);b.putBoolean("truncated",truncated);return b;}}}
    private static void shellHelperEnvironment(Map<String,String> env){Map<String,String> inherited=new HashMap<>(System.getenv());env.clear();env.put("PATH","/system/bin:/system/xbin:/vendor/bin");env.put("HOME","/data/local/tmp");env.put("TMPDIR","/data/local/tmp");env.put("LANG","C.UTF-8");String[] roots={"ANDROID_ROOT","ANDROID_DATA","ANDROID_ART_ROOT","ANDROID_I18N_ROOT","ANDROID_TZDATA_ROOT"};for(String k:roots){String v=inherited.get(k);if(v!=null&&v.startsWith("/"))env.put(k,v);}String[] boot={"BOOTCLASSPATH","DEX2OATBOOTCLASSPATH"};for(String k:boot){String v=inherited.get(k);if(v!=null&&!v.isEmpty())env.put(k,v);}}
}
